import { getDatabaseAdapter, type CorrectionCategory, type CorrectionSeverity, type ExamStatus, type FollowUp } from '#lib/adapters/db/index.js';
import takes from './longTakes.json';

/**
 * Two simulated long takes, 3 and 5 minutes of spoken French with mistakes in
 * about a quarter of the sentences (generated by scripts/simulate-long-takes.py),
 * for seeing how cards cope with long text. Development only: the
 * /dev/long-takes/ page adds them.
 */

interface SimulatedTake {
	prompt: string;
	durationSec: number;
	transcript: string;
	correctedText: string;
	wordCount: number;
	explanation: string;
	followUp: FollowUp;
	corrections: Array<{
		category: string;
		severity: string;
		label: string;
		original: string;
		replacement: string;
		replacementTranslation: string;
		explanation: string;
		examStatus: string | null;
	}>;
}

/** Every simulated session's id starts with this, which is how an existing one is found again. */
const SESSION_ID_PREFIX = 'session-long-takes-';

/**
 * The simulated session: the one added before if it is still there, else a
 * new one with both takes, beside the learner's own (delete it from History
 * when done; the next call adds it again).
 *
 * @returns The session's id.
 */
export async function longTakesSession(): Promise<string> {
	const db = await getDatabaseAdapter();
	const existing = (await db.listSessions()).find((session) => session.id.startsWith(SESSION_ID_PREFIX));
	return existing?.id ?? addLongTakes();
}

/**
 * Adds both takes as a new session.
 *
 * @returns The new session's id.
 */
async function addLongTakes(): Promise<string> {
	const db = await getDatabaseAdapter();
	const started = Date.now();
	const sessionId = `${SESSION_ID_PREFIX}${started}`;
	const at = (offsetMs: number) => new Date(started + offsetMs).toISOString();

	await db.putSession({
		id: sessionId,
		title: 'Long takes (simulated)',
		mode: 'casual',
		startedAt: at(0),
		endedAt: null,
		createdAt: at(0),
		updatedAt: at(60_000)
	});

	for (const [index, take] of (takes as SimulatedTake[]).entries()) {
		const id = `attempt-long-takes-${started}-${index}`;
		const createdAt = at(index * 30_000);
		await db.putAttempt({
			id,
			sessionId,
			promptId: null,
			promptText: take.prompt,
			transcript: take.transcript,
			correctedText: take.correctedText,
			translation: null,
			translations: null,
			ttsVoice: null,
			explanation: take.explanation,
			followUp: take.followUp,
			wordGlosses: null,
			durationSec: take.durationSec,
			wordCount: take.wordCount,
			audioKey: null,
			createdAt,
			updatedAt: createdAt
		});
		await db.replaceCorrections(
			id,
			take.corrections.map((correction, sortOrder) => ({
				id: `${id}-correction-${sortOrder}`,
				attemptId: id,
				category: correction.category as CorrectionCategory,
				severity: correction.severity as CorrectionSeverity,
				label: correction.label,
				original: correction.original,
				replacement: correction.replacement,
				replacementTranslation: correction.replacementTranslation,
				start: null,
				end: null,
				explanation: correction.explanation,
				speakText: null,
				examStatus: correction.examStatus as ExamStatus | null,
				formalAlternatives: [],
				sortOrder,
				createdAt
			}))
		);
	}
	return sessionId;
}
